async function piAirbnbOtpDeliveryKind(page) {
  const text = (await page.locator('body').innerText().catch(function () { return ''; })).replace(/\s+/g, ' ').trim();
  if (/whats\s*app/i.test(text)) return 'whatsapp';
  if (/email/i.test(text) && !/text message|\bsms\b|\bphone\b|mobile|we texted|sent a text|texted a code/i.test(text)) return 'email';
  if (/text message|\bsms\b|\bphone\b|mobile|we texted|sent a text|texted a code/i.test(text)) return 'sms';
  return 'unknown';
}
async function piAirbnbOtpDeliveryHint(page, meta) {
  meta = meta || {};
  const text = (await page.locator('body').innerText().catch(function () { return ''; })).replace(/\s+/g, ' ').trim();
  const email = (text.match(/[\w.+-]+@[\w.-]+\.\w+/) || [])[0];
  const phone = (text.match(/\*{2,}\d{2,4}|\d{2,3}\*{2,}\d{2,4}|ending in\s*\d{2,4}/i) || [])[0];
  const kind = meta.delivery || await piAirbnbOtpDeliveryKind(page);
  if (meta.smsStuck || (kind === 'sms' && meta.canEmail === false)) {
    return 'Airbnb only offered SMS for this server login' + (phone ? (' (' + phone + ')') : '') +
      '. Texts usually never arrive here. Cancel Connect and use Paste session JSON from your normal browser.';
  }
  if (kind === 'email') {
    return 'Airbnb usually emails this code' + (email ? (' to ' + email) : ' (check the host inbox + spam)') + '.';
  }
  if (kind === 'whatsapp') {
    return 'Airbnb says it sent a WhatsApp code' + (phone ? (' (' + phone + ')') : '') + '. Check WhatsApp on the host phone.';
  }
  if (kind === 'sms') {
    return 'Airbnb says it sent a text' + (phone ? (' (' + phone + ')') : '') +
      '. If it does not arrive within a minute, tap Resend as email — or Paste session JSON if email is not offered.';
  }
  return 'Check the Airbnb host email inbox first (and spam). SMS often does not arrive for this login.';
}
async function piAirbnbClickMatching(page, patterns, opts) {
  opts = opts || {};
  const maxLen = opts.maxLen || 100;
  const clicked = await page.evaluate(function (args) {
    var pats = args.patterns || [];
    var maxLen = args.maxLen || 100;
    function norm(s) { return String(s || '').replace(/\s+/g, ' ').trim(); }
    var res = [];
    for (var i = 0; i < pats.length; i++) {
      try { res.push(new RegExp(pats[i], 'i')); } catch (e) {}
    }
    var nodes = Array.prototype.slice.call(document.querySelectorAll(
      'button, a, [role="button"], [role="link"], [role="menuitem"], [role="option"], label, summary'
    ));
    var extras = Array.prototype.slice.call(document.querySelectorAll('div, span, p, li'));
    for (var e = 0; e < extras.length; e++) {
      var el = extras[e];
      var t0 = norm(el.innerText);
      if (!t0 || t0.length > maxLen) continue;
      if (el.childElementCount > 4) continue;
      nodes.push(el);
    }
    var seen = [];
    for (var n = 0; n < nodes.length; n++) {
      var node = nodes[n];
      if (!node || seen.indexOf(node) >= 0) continue;
      seen.push(node);
      var t = norm(node.innerText || node.textContent);
      if (!t || t.length > maxLen) continue;
      var ok = false;
      for (var r = 0; r < res.length; r++) {
        if (res[r].test(t)) { ok = true; break; }
      }
      if (!ok) continue;
      try {
        node.scrollIntoView({ block: 'center', inline: 'nearest' });
        node.click();
        return t;
      } catch (err) {}
    }
    return null;
  }, { patterns: patterns, maxLen: maxLen });
  if (clicked) await page.waitForTimeout(opts.wait || 1400);
  return clicked;
}
async function piAirbnbListClickables(page) {
  return page.evaluate(function () {
    function norm(s) { return String(s || '').replace(/\s+/g, ' ').trim(); }
    var out = [];
    var nodes = document.querySelectorAll('button, a, [role="button"], [role="link"], [role="menuitem"], label');
    for (var i = 0; i < nodes.length; i++) {
      var t = norm(nodes[i].innerText || nodes[i].textContent);
      if (!t || t.length > 80) continue;
      if (out.indexOf(t) < 0) out.push(t);
      if (out.length >= 30) break;
    }
    return out;
  }).catch(function () { return []; });
}
async function piAirbnbOpenOtpOptions(page) {
  return !!(await piAirbnbClickMatching(page, [
    'more options', 'other options', 'try another', 'another way', 'another method',
    'get a code another', 'need help', "didn'?t get", 'did not get', "haven'?t received",
    'have not received', 'choose a different', 'different method', 'άλλες επιλογές',
    'άλλος τρόπος', 'δεν έλαβα', 'βοήθεια'
  ], { wait: 1200 }));
}
async function piAirbnbPreferEmailDelivery(page) {
  var kind0 = await piAirbnbOtpDeliveryKind(page);
  if (kind0 === 'email') return 'email';
  var emailPats = [
    '^email$', '^e-mail$', 'email me', 'email a code', 'email me a code',
    'send (an )?email', 'get a code by email', 'send code by email', 'receive.*by email',
    'code by email', 'αποστολή.*email', 'με email', 'ηλεκτρονικ'
  ];
  var hit = await piAirbnbClickMatching(page, emailPats, { wait: 1800 });
  if (hit) return 'email';
  await piAirbnbOpenOtpOptions(page);
  hit = await piAirbnbClickMatching(page, emailPats, { wait: 2000 });
  if (hit) return 'email';
  // WhatsApp sometimes works when SMS does not
  hit = await piAirbnbClickMatching(page, ['^whatsapp$', 'whats\s*app'], { wait: 1800 });
  if (hit) return 'whatsapp';
  return null;
}
async function piAirbnbResendCode(page, preferEmail) {
  if (preferEmail) await piAirbnbPreferEmailDelivery(page);
  var resentPats = [
    '^resend$', 'resend code', 'send again', 'send code again', 'get a new code',
    "didn'?t get a code", 'did not get a code', "haven'?t received", 'ξαναστείλε', 'νέος κωδικός'
  ];
  var hit = await piAirbnbClickMatching(page, resentPats, { wait: 2000 });
  if (hit) {
    if (preferEmail) await piAirbnbPreferEmailDelivery(page);
    return true;
  }
  await piAirbnbOpenOtpOptions(page);
  if (preferEmail) await piAirbnbPreferEmailDelivery(page);
  hit = await piAirbnbClickMatching(page, resentPats, { wait: 2000 });
  if (hit) return true;
  // Selecting email on a method chooser often triggers a fresh send
  if (preferEmail) {
    var again = await piAirbnbPreferEmailDelivery(page);
    if (again === 'email' || again === 'whatsapp') return true;
  }
  return false;
}
async function piAirbnbFillOtp(page, otp) {
  const otpInput = page.locator('input[name*="code" i], input[autocomplete="one-time-code"], input[inputmode="numeric"], input[type="tel"]').first();
  if (!(await otpInput.count())) throw new Error('OTP input not found on Airbnb page');
  await otpInput.fill(String(otp));
  await page.locator('button:has-text("Continue"), button:has-text("Submit"), button[type="submit"]').first().click().catch(function () {});
  await page.waitForTimeout(3500);
}
async function piAirbnbRefreshOtpMeta(job) {
  const preferred = await piAirbnbPreferEmailDelivery(job.page);
  let delivery = await piAirbnbOtpDeliveryKind(job.page);
  if (preferred === 'email') delivery = 'email';
  if (preferred === 'whatsapp' && delivery === 'unknown') delivery = 'whatsapp';
  job.delivery = delivery;
  job.canEmail = delivery === 'email' || preferred === 'email';
  job.smsStuck = delivery === 'sms' && !job.canEmail;
  job.hint = await piAirbnbOtpDeliveryHint(job.page, {
    delivery: job.delivery,
    canEmail: job.canEmail,
    smsStuck: job.smsStuck
  });
  job.updatedAt = Date.now();
  try {
    job.pageSnippet = (await job.page.locator('body').innerText().catch(function () { return ''; })).replace(/\s+/g, ' ').trim().slice(0, 320);
  } catch (e) { job.pageSnippet = ''; }
  try {
    job.clickables = await piAirbnbListClickables(job.page);
  } catch (e) { job.clickables = []; }
}
async function piAirbnbMarkAwaitingOtp(job) {
  await piAirbnbPreferEmailDelivery(job.page);
  try { await job.page.waitForTimeout(800); } catch (e) {}
  await piAirbnbPreferEmailDelivery(job.page);
  job.status = 'awaiting_otp';
  await piAirbnbRefreshOtpMeta(job);
}

